from pathlib import Path
import re, subprocess, json
files=subprocess.check_output(['git','ls-files'], text=True).splitlines()
md=[Path(x) for x in files if x.lower().endswith('.md')]
text_ext={'.md','.txt','.json','.yml','.yaml','.c','.h','.sh','.py'}
polish_chars=re.compile(r'[ąćęłńóśźżĄĆĘŁŃÓŚŹŻ]')
polish_words=re.compile(r'\b(zostal|zostala|zostalo|nalezy|powinien|powinna|mozna|jezeli|sprawdz|uruchom|repozytorium|dokumentacja|uzyj|uzywa|wymaga|poniewaz)\b', re.I)
lang=[]
for f in map(Path,files):
    if f.suffix.lower() not in text_ext and f.name not in {'CMakeLists.txt','Kconfig.projbuild'}: continue
    try:s=f.read_text()
    except UnicodeDecodeError:continue
    for n,line in enumerate(s.splitlines(),1):
        if polish_chars.search(line) or polish_words.search(line): lang.append((str(f),n,line[:220]))
print('MARKDOWN_FILES=',len(md))
print('LANGUAGE_SUSPECTS=',len(lang))
for x in lang: print('LANG',*x,sep=' | ')
issues=[]
for f in md:
    lines=f.read_text().splitlines()
    hs=[]; fence=False; fence_line=0
    h1=0
    prev_level=0
    for i,line in enumerate(lines,1):
        if line.rstrip()!=line: issues.append((str(f),i,'trailing-whitespace'))
        if '\t' in line: issues.append((str(f),i,'tab'))
        m=re.match(r'^(#{1,6})\s+(.+)$',line)
        if m and not fence:
            lev=len(m.group(1)); hs.append((i,lev,m.group(2))); h1 += lev==1
            if prev_level and lev>prev_level+1: issues.append((str(f),i,f'heading-jump-{prev_level}-to-{lev}'))
            prev_level=lev
        if line.startswith('```'):
            if not fence:
                fence=True; fence_line=i
                if line.strip()=='```': issues.append((str(f),i,'code-fence-no-language'))
            else: fence=False
    if fence: issues.append((str(f),fence_line,'unclosed-code-fence'))
    if h1!=1: issues.append((str(f),1,f'h1-count-{h1}'))
    for i in range(2,len(lines)):
        if lines[i-1]=='' and lines[i]=='' and lines[i-2]=='': issues.append((str(f),i+1,'3+-consecutive-blank-lines'))
    # Relative Markdown link targets.
    for i,line in enumerate(lines,1):
        for target in re.findall(r'\[[^]]+\]\(([^)]+)\)',line):
            t=target.split('#',1)[0]
            if not t or '://' in t or t.startswith('mailto:'): continue
            p=(f.parent/t).resolve()
            if not p.exists(): issues.append((str(f),i,'broken-relative-link:'+target))
    # UX heuristics: very long prose paragraph and giant handoff docs.
    para=[]; start=1
    for i,line in enumerate(lines+[''],1):
        if line and not line.startswith('#') and not line.startswith('- ') and not line.startswith('```'):
            if not para:start=i
            para.append(line)
        else:
            if para and len(' '.join(para))>900: issues.append((str(f),start,'long-paragraph>900chars'))
            para=[]
    if len(lines)>500: issues.append((str(f),1,f'large-document-{len(lines)}-lines'))
print('MARKDOWN_ISSUES=',len(issues))
for x in issues: print('MD',*x,sep=' | ')
# High-level README UX checks
r=Path('README.md').read_text().lower()
for key,terms in {'purpose':['## purpose','## why'], 'quickstart':['## quick start','## getting started'], 'docs':['documentation','docs/'], 'architecture':['## architecture']}.items():
    print('README_'+key.upper()+'=', any(t in r for t in terms))
print('DOC_UX_AUDIT=PASS')
